gq6(){return"TruthLens\ub294 \uc0ac\uc6a9\uc790\uc758 \uc2e0\uc6d0\uacfc \uc5f0\uacb0\ub41c \ub370\uc774\ud130\ub97c \uc804\ud600 \uc218\uc9d1\ud558\uc9c0 \uc54a\uc73c\uba70 \ucd94\uc801 \ubaa9\uc801\uc73c\ub85c \uc5b4\ub5a4 \ub370\uc774\ud130\ub3c4 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uc571 \ucd94\uc801 \ud22c\uba85\uc131\uff08ATT\uff09 \uad8c\ud55c\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gq7(){return"\uc774 \uc571\uc740 \uc2dc\uc2a4\ud15c\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 \ud30c\uc77c \uc120\ud0dd \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc0ac\uc6a9\uc790\uac00 \ub2a5\ub3d9\uc801\uc73c\ub85c \uc120\ud0dd\ud55c \ubb38\uc11c\ub098 \uc774\ubbf8\uc9c0\uc5d0 \uc811\uadfc\ud569\ub2c8\ub2e4. \uc120\ud0dd\ud558\uc9c0 \uc54a\uc740 \ud30c\uc77c\uc5d0\ub294 \uc811\uadfc\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4\uff08iOS \uc571 \uc0cc\ub4dc\ubc15\uc2a4 \uc81c\ud55c\uff09."},
gpZ(){return"TruthLens\ub294 \uac1c\uc778 \ub370\uc774\ud130\ub97c \uc218\uc9d1\ud558\uc9c0 \uc54a\uc73c\uba70 \uc5b4\ub5a4 \uc81c3\uc790\uc640\ub3c4 \uc0ac\uc6a9\uc790 \ub370\uc774\ud130\ub97c \uacf5\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gq_(){return"\uc774 \uc571\uc740 \uc0ac\uc6a9\uc790\uac00 \ub2a5\ub3d9\uc801\uc73c\ub85c \ubb38\uc11c\ub098 \uc774\ubbf8\uc9c0 \uac00\uc838\uc624\uae30\ub97c \uc120\ud0dd\ud560 \ub54c\ub9cc \ud574\ub2f9 \uc800\uc7a5\uc18c \uad8c\ud55c\uc5d0 \uc811\uadfc\ud558\uba70, \ubc31\uadf8\ub77c\uc6b4\ub4dc\uc5d0\uc11c \ub2e4\ub978 \ud30c\uc77c\uc744 \uc2a4\uce94\ud558\uac70\ub098 \uc811\uadfc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gq9(){return"TruthLens\ub294 macOS \uc571 \uc0cc\ub4dc\ubc15\uc2a4 \ud558\uc5d0\uc11c \uc2e4\ud589\ub418\uba70, \uc2dc\uc2a4\ud15c \ud30c\uc77c \ub300\ud654 \uc0c1\uc790\ub97c \ud1b5\ud574 \uc0ac\uc6a9\uc790\uac00 \ub2a5\ub3d9\uc801\uc73c\ub85c \uc120\ud0dd\ud55c \ud30c\uc77c\uff08files.user-selected.read-write\uff09\uc5d0\ub9cc \uc811\uadfc\ud560 \uc218 \uc788\uace0, \ub2e4\ub978 \ud30c\uc77c\uc774\ub098 \ud3f4\ub354\ub97c \uc790\uc720\ub86d\uac8c \ud0d0\uc0c9\ud558\uac70\ub098 \uc811\uadfc\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4."},
gqa(){return'\ub124\ud2b8\uc6cc\ud06c \uc811\uadfc \uad8c\ud55c\uff08network.client\uff09\uc740 \uc544\ub798 "\ud544\uc694\ud55c \uc5f0\uacb0 \ub3d9\uc791"\uc5d0 \ub098\uc5f4\ub41c \uae30\ub2a5\uc5d0\ub9cc \uc0ac\uc6a9\ub429\ub2c8\ub2e4.'},
gqs(){return"TruthLens\ub294 \ub3c5\ub9bd \uc2e4\ud589\ud615 \ub370\uc2a4\ud06c\ud1b1 \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc73c\ub85c, \ub370\uc774\ud130\ub294 \ub85c\uceec \uc0ac\uc6a9\uc790 \ud3f4\ub354\uff08AppData\uff0fDocuments \ub4f1\uff09\uc5d0 \uc800\uc7a5\ub418\uba70 \ud074\ub77c\uc6b0\ub4dc\uc5d0 \ub3d9\uae30\ud654\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
